import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { participateSpace } from "../handlers/participateSpace";
import type { ApiError } from "../runtime/client";
import type { ParticipateSpaceRequest } from "../types/ParticipateSpaceRequest";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof participateSpace>>;
type Vars = { spaceId: SpacePartition; body: ParticipateSpaceRequest };

export function useParticipateSpace(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => participateSpace(vars.spaceId, vars.body),
    ...options,
  });
}
